import{_ as a,o,c as n,a2 as i}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Introducción: un mundo vivo que toma forma con sus habitantes","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/introduction.md","filePath":"es/guide/introduction.md"}'),r={name:"es/guide/introduction.md"};function t(s,e,d,c,l,u){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="introduction-a-living-world-shaped-by-its-people" tabindex="-1">Introducción: un mundo vivo que toma forma con sus habitantes <a class="header-anchor" href="#introduction-a-living-world-shaped-by-its-people" aria-label="Enlace permanente a &quot;Introducción: un mundo vivo que toma forma con sus habitantes&quot;">​</a></h1><p><strong>Estado:</strong> Visión del diseño · Modern Combat y los sistemas ampliados de mundo, artesanía y magia tienen estado Propuesto; los valores del prototipo tienen estado Experimental. Las bases con estado Aceptado conservan su alcance indicado. Las funciones descritas no están necesariamente disponibles para jugar.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Syrolands explora un mundo sandbox vivo donde importan el entorno, tus conocimientos y tus decisiones.</li><li>El combate busca ser fácil de manejar y difícil de dominar, con las opciones Modern y Legacy.</li><li>Los oficios, la exploración y la magia ofrecen identidades más allá de una única escala de poder de combate.</li></ul><h2 id="a-world-that-can-change-your-plans" tabindex="-1">Un mundo que puede cambiar tus planes <a class="header-anchor" href="#a-world-that-can-change-your-plans" aria-label="Enlace permanente a &quot;Un mundo que puede cambiar tus planes&quot;">​</a></h2><p>Sales por un camino conocido, pero un árbol caído bloquea el paso estrecho. Rodearlo lleva tiempo; retirarlo requiere herramientas; el obstáculo puede ser útil para quien defiende el cruce. Esta es la propuesta de mundo vivo: los recursos, el terreno y los objetos pueden afectar físicamente a las rutas y los conflictos.</p><p>Syrolands es un laboratorio sandbox inspirado en la libertad de Ultima Online. No necesitas conocer ese juego para entender la idea: desarrollar un personaje mediante lo que aprendes y haces, y encontrar tu lugar en un mundo compartido. Los cambios ambientales necesitan límites y reglas de recuperación; un mundo interactivo no promete que todo pueda destruirse.</p><h2 id="combat-with-room-to-grow" tabindex="-1">Combate con margen para crecer <a class="header-anchor" href="#combat-with-room-to-grow" aria-label="Enlace permanente a &quot;Combate con margen para crecer&quot;">​</a></h2><p>Modern Combat es la dirección experimental preferida: seleccionas un objetivo e inicias una acción disponible cuando decides comprometerte. Legacy Auto-Attack se mantiene como alternativa compatible con el diseño y utiliza una cadencia automática. Ambos deben ser accesibles y compartir reglas justas y legibles; aquí no se anuncia ninguno como una nueva opción ya jugable.</p><table tabindex="0"><thead><tr><th>Lo que interpretas</th><th>Por qué importa</th></tr></thead><tbody><tr><td>Distancia y alcance</td><td>La ventaja de una lanza a distancia puede convertirse en dificultad de manejo de cerca</td></tr><tr><td>Tiempo y stamina</td><td>Una acción exigente genera presión, pero fallar deja una recuperación que el rival puede aprovechar</td></tr><tr><td>Special Attacks y Flow</td><td>Las opciones aprendidas y un ritmo sostenible premian el criterio, no pulsar sin parar</td></tr><tr><td>Trauma local y equipo</td><td>El estado de una extremidad o de una pieza de armadura puede cambiar la situación</td></tr></tbody></table><p>El objetivo es un manejo sencillo con decisiones profundas. La ejecución del jugador y la experiencia del personaje conviven; la información ayuda a elegir sin garantizar un impacto.</p><h2 id="knowledge-is-useful-in-the-moment" tabindex="-1">Conocimientos útiles en el momento <a class="header-anchor" href="#knowledge-is-useful-in-the-moment" aria-label="Enlace permanente a &quot;Conocimientos útiles en el momento&quot;">​</a></h2><p>Anatomy, Arms Lore, Animal Lore y Tracking apuntan a formas distintas de comprender cuerpos, equipo, criaturas y rastros. Las habilidades deben aportar información y capacidad útiles. Reconocer un problema no lo resuelve automáticamente, y saber más no debería revelar todas las cifras ocultas.</p><h2 id="crafts-belong-to-adventurers" tabindex="-1">Los oficios también son para aventureros <a class="header-anchor" href="#crafts-belong-to-adventurers" aria-label="Enlace permanente a &quot;Los oficios también son para aventureros&quot;">​</a></h2><p>Las profesiones deben aportar utilidad en el campo, apoyo en combate y valor económico, sin exigir un personaje alternativo dedicado exclusivamente a fabricar. Un cocinero ayuda a preparar una expedición; un alquimista aporta mezclas útiles; un herrero o un sastre entiende el equipo dañado. Carpentry y Tinkering pueden contribuir a estructuras, herramientas y mecanismos.</p><p>La artesanía se propone como un trabajo interactivo condicionado por los materiales y la ejecución. Las técnicas, la experimentación, la reputación y el conocimiento importan junto a la habilidad. Ser conocido por un equipo de campaña fiable o una comida extraordinaria puede dar identidad al personaje.</p><h2 id="discover-your-specialty" tabindex="-1">Descubre tu especialidad <a class="header-anchor" href="#discover-your-specialty" aria-label="Enlace permanente a &quot;Descubre tu especialidad&quot;">​</a></h2><p>Instructores, academias, libros, culturas, ruinas, misiones y exploración pueden enseñar técnicas o hechizos. <strong>Skill ≠ Technique ≠ Familiarity ≠ Mastery</strong>: capacidad, opciones aprendidas, fluidez practicada y dominio profundo están relacionados, pero son distintos. Llegar al máximo de una habilidad no debería revelarlo todo. Dos expertos pueden ser conocidos por especialidades muy diferentes.</p><h2 id="magic-is-learned-and-prepared" tabindex="-1">La magia se aprende y se prepara <a class="header-anchor" href="#magic-is-learned-and-prepared" aria-label="Enlace permanente a &quot;La magia se aprende y se prepara&quot;">​</a></h2><p>Un hechizo comienza con un <strong>Core Pattern</strong> aprendido, su estructura base. Magery favorece la ejecución, Familiarity refleja la práctica y Active Memory selecciona los patrones preparados. Conocer un hechizo no equivale a tenerlo preparado; estar preparado tampoco significa lanzarlo al instante.</p><p>Los libros de hechizos, pergaminos y reactivos tienen funciones tácticas y económicas propuestas. Inscription conserva y modifica el conocimiento mágico mediante notación, variantes y obras físicas. La capacidad, los tiempos de consulta y muchos costes siguen abiertos.</p><h2 id="items-with-a-story" tabindex="-1">Objetos con historia <a class="header-anchor" href="#items-with-a-story" aria-label="Enlace permanente a &quot;Objetos con historia&quot;">​</a></h2><p>La calidad significa más que daño bruto: importan el manejo, la consistencia, la integridad, la conservación del rendimiento y los rasgos significativos. Un Masterwork es un logro excepcional, no un objeto mágico automático. Las propiedades latentes podrían hacer memorables ciertos objetos mediante el uso y el descubrimiento, mientras el buen equipo ordinario sigue siendo útil y el equipo valioso continúa expuesto a pérdidas.</p><h2 id="more-than-one-endgame" tabindex="-1">Más de una meta a largo plazo <a class="header-anchor" href="#more-than-one-endgame" aria-label="Enlace permanente a &quot;Más de una meta a largo plazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Camino</th><th>Una posible aspiración</th></tr></thead><tbody><tr><td>Marcial</td><td>Ser un duelista respetado o un compañero de caza fiable</td></tr><tr><td>Artesanía</td><td>Desarrollar una especialidad reconocible y una reputación por tu trabajo</td></tr><tr><td>Conocimiento y exploración</td><td>Descubrir técnicas, materiales, lugares o tradiciones mágicas</td></tr><tr><td>Economía</td><td>Establecer relaciones comerciales de confianza y suministrar bienes útiles</td></tr><tr><td>Social y político</td><td>Organizar una comunidad o influir en proyectos compartidos</td></tr><tr><td>Reputación</td><td>Ser conocido por lo que aportas, no solo por tus puntos de habilidad</td></tr></tbody></table><p>Son aspiraciones de diseño, no una lista de sistemas entregados. Empieza por la <a href="/Syrolands-Public/es/guide/">Guía</a> para explorar un camino o consulta la <a href="/Syrolands-Public/es/game-design/vision.html">visión del proyecto</a> para conocer el contexto detallado del diseño.</p>',26)])])}const b=a(r,[["render",t]]);export{m as __pageData,b as default};
